export const DEFAULT_PHOTO = "data-centre-aisle";

/** A relevant, licensed photograph for the illustration scene being rendered. */
export function resolvePhoto(visual3d?: string): Photo {
  const id = (visual3d && PHOTO_BY_SCENE[visual3d]) || PHOTO_BY_FAMILY[(visual3d ?? '').split('/')[0]] || DEFAULT_PHOTO;
  return PHOTO_LIBRARY[id] ?? PHOTO_LIBRARY[DEFAULT_PHOTO];
}
